changeSet.sql:
UPDATE device_credential_set
SET auth_type = UPPER(auth_type)
WHERE dtype = 'DeviceSnmpv3Community' AND auth_type IS NOT NULL;

UPDATE device_credential_set
SET priv_type = UPPER(priv_type)
WHERE dtype = 'DeviceSnmpv3Community' AND priv_type IS NOT NULL;

UPDATE device_credential_set
SET priv_type = 'DES3'
WHERE dtype = 'DeviceSnmpv3Community' AND priv_type = 'DES';

UPDATE web_hook
SET https_ca_trust_mode = 'TRUST_ANY'
WHERE ssl_validation = false;

UPDATE device_access
SET https_ca_trust_mode = 'TRUST_ANY'
WHERE https_verify_hostname = false AND https_ca_trust_mode != 'TRUST_ANY';
